"use client";

import { useEffect, useState } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import api from "@/utils/api"; 

const VerifyEmail = () => {
  const searchParams = useSearchParams();
  const router = useRouter();
  const token = searchParams.get("token");

  const [status, setStatus] = useState<"loading" | "success" | "error">("loading");

  useEffect(() => {
    if (!token) {
      setStatus("error");
      return;
    }

    const verifyEmail = async () => {
      console.log("Verifying token:", token); 

      try {
        // Gantilah fetch dengan axios api.get
        const response = await api.get(`/v1/auth/verify-email?token=${token}`);
        
        // Jika status respons tidak OK, throw error
        if (response.status !== 200) {
          console.error("Response not OK:", response);
          throw new Error("Invalid or expired token");
        }

        console.log("Server response:", response.data); // Menampilkan respons server

        setStatus("success");
        setTimeout(() => router.push(`/auth/setup-password?token=${token}`), 2000);
      } catch (error) {
        console.error("Error during verification:", error);
        setStatus("error");
      }
    };

    verifyEmail();
  }, [token, router]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen">
      {status === "loading" && <p className="text-gray-600">Verifying your email...</p>}
      {status === "success" && (
        <p className="text-green-600 font-semibold">
          Email verified! Redirecting to password setup...
        </p>
      )}
      {status === "error" && (
        <p className="text-red-500 font-semibold">
          Verification failed. The link may be expired or invalid.
        </p>
      )}
    </div>
  );
};

export default VerifyEmail;
